function formatDate(s){if(!s)return'';const p=s.split('-');return p.length===3?`${p[2]}.${p[1]}.${p[0]}`:s}
function fitText(text,x,y,maxW,start=52,min=20,weight=700,color='#111',family='"Arial Narrow", Arial, sans-serif'){if(!text)return;ctx.save();ctx.fillStyle=color;let size=start;ctx.font=`${weight} ${size}px ${family}`;while(ctx.measureText(text).width>maxW&&size>min){size-=1;ctx.font=`${weight} ${size}px ${family}`}ctx.fillText(text,x,y);ctx.restore()}
function wrap(text,x,y,maxW,lineH,fontSize=20,maxLines=2,weight=400,color='#111',family='"Arial Narrow", Arial, sans-serif'){if(!text)return;ctx.save();ctx.fillStyle=color;ctx.font=`${weight} ${fontSize}px ${family}`;const words=(text||'').split(/\s+/).filter(Boolean);let line='',lines=[];for(const w of words){const test=line?line+' '+w:w;if(ctx.measureText(test).width>maxW&&line){lines.push(line);line=w}else line=test}if(line)lines.push(line);lines.slice(0,maxLines).forEach((l,i)=>ctx.fillText(l,x,y+i*lineH));ctx.restore()}
function wrapBox(text,x,y,maxW,maxH,lineH=24,fontSize=20,maxLines=2,weight=400,color='#111'){if(!text)return;ctx.save();ctx.rect(x,y-20,maxW,maxH);ctx.clip();ctx.fillStyle=color;ctx.font=`${weight} ${fontSize}px "Roboto Condensed", "Arial Narrow", Arial, sans-serif`;const tokens=(text||'').split(/\s+/).filter(Boolean);const lines=[];let line='';for(const token of tokens){let word=token;while(ctx.measureText(word).width>maxW){let part='';for(const ch of word){if(ctx.measureText(part+ch).width>maxW)break;part+=ch}if(line){lines.push(line);line=''}lines.push(part);word=word.slice(part.length)}const test=line?line+' '+word:word;if(ctx.measureText(test).width>maxW&&line){lines.push(line);line=word}else line=test}if(line)lines.push(line);const visible=lines.slice(0,Math.min(maxLines,Math.floor(maxH/lineH)));visible.forEach((l,i)=>{let out=l;if(i===visible.length-1&&lines.length>visible.length){while(ctx.measureText(out+'…').width>maxW&&out.length>1)out=out.slice(0,-1);out+='…'}ctx.fillText(out,x,y+i*lineH)});ctx.restore()}
function drawCoverPhoto(img,x,y,w,h,r=16){ctx.save();roundRect(x,y,w,h,r);ctx.clip();const scale=Math.max(w/img.width,h/img.height);const dw=img.width*scale,dh=img.height*scale;const dx=x+(w-dw)/2,dy=dh>h?y+(h-dh)*0.12:y+(h-dh)/2;ctx.drawImage(img,dx,dy,dw,dh);ctx.restore()}
function render(){if(!bg.complete)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(bg,0,0,canvas.width,canvas.height);if(photoImg)drawCoverPhoto(photoImg,42,278,445,558,18);fitText(val('lastName').toUpperCase(),525,430,420,62,34,600,'#080808','Oswald, "Arial Narrow", Arial, sans-serif');fitText(val('firstMiddleName'),525,497,420,45,26,600,'#080808','Oswald, "Arial Narrow", Arial, sans-serif');fitText(val('age'),525,552,360,28,20,500,'#111','"Roboto Condensed", "Arial Narrow", Arial, sans-serif');fitText(formatDate(val('date')),785,690,172,23,18,500,'#c00000','"Roboto Condensed", "Arial Narrow", Arial, sans-serif');wrap(val('place'),580,792,365,32,27,3,500,'#111','"Roboto Condensed", "Arial Narrow", Arial, sans-serif');wrapBox(val('height'),130,953,177,39,24,20,1,400);wrapBox(val('build'),224,992,231,52,24,20,2,400);wrapBox(val('hair'),158,1028,306,52,24,20,2,400);wrapBox(val('eyes'),148,1065,269,39,24,20,1,400);wrapBox(val('special'),244,1104,210,68,23,20,3,400);wrapBox(val('jacket'),623,953,369,60,24,20,2,400);wrapBox(val('pants'),623,992,374,39,24,20,1,400);wrapBox(val('shoes'),623,1034,369,39,24,20,1,400);wrapBox(val('carrying'),644,1075,357,58,24,20,2,400);fitText(formatDate(val('actual')),530,1521,155,20,15,500,'#fff','"Roboto Condensed", "Arial Narrow", Arial, sans-serif')}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
